(function(){var config=window.easyUtmCf7||{};var cookieDays=parseInt(config.cookieDays,10)||60;var trackedParams=config.params||['utm_source','utm_medium','utm_term','utm_campaign','utm_content','gclid','fbclid','msclkid','ttclid'];function createCookie(name,value,days){var expires='';if(days){var date=new Date();date.setTime(date.getTime()+days*24*60*60*1000);expires='; expires='+date.toUTCString()}
document.cookie=name+'='+value+expires+'; path=/; SameSite=Lax'}
function readCookie(name){var nameEQ=name+'=';var ca=document.cookie.split(';');for(var i=0;i<ca.length;i++){var c=ca[i];while(c.charAt(0)===' '){c=c.substring(1)}
if(c.indexOf(nameEQ)===0){return c.substring(nameEQ.length)}}
return null}
function getParams(){var search=window.location.search;var found={};var hasAny=!1;if(!search){return null}
var query=search.substring(1).split('&');for(var i=0;i<query.length;i++){var pair=query[i].split('=');var key=decodeURIComponent(pair[0]||'');if(trackedParams.indexOf(key)===-1){continue}
var value=decodeURIComponent((pair[1]||'').replace(/\+/g,' '));if(value!==''){found[key]=value;hasAny=!0}}
return hasAny?found:null}
var params=getParams();if(params){params.landing=window.location.href.split('?')[0];params.ts=Math.floor(Date.now()/1000);var encoded=encodeURIComponent(JSON.stringify(params));createCookie('_easy_utm_last',encoded,cookieDays);if(!readCookie('_easy_utm_first')){createCookie('_easy_utm_first',encoded,cookieDays)}}
var internalPrefix=location.protocol+'//'+location.host;if(document.referrer&&document.referrer.indexOf(internalPrefix)!==0&&!readCookie('_easy_utm_referrer')){createCookie('_easy_utm_referrer',encodeURIComponent(document.referrer),cookieDays)}})();